import{_ as o,W as i,s as d,u as r,ah as l,I as e,w as n,Z as a,A as t}from"./chunks/framework.B4JzB-Td.js";import"./chunks/theme.Xs8fIzCW.js";const v=JSON.parse('{"title":"如何清理 Snap 版本以释放磁盘空间 | LCTT x X-CMD","titleTemplate":false,"description":"如何清理 Snap 版本以释放磁盘空间 | LCTT (202211) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"如何清理 Snap 版本以释放磁盘空间 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何清理 Snap 版本以释放磁盘空间 | LCTT (202211) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202211/20221019.2 ⭐️  How to Clean Up Snap Versions to Free Up Disk Space","title":"如何清理 Snap 版本以释放磁盘空间","tag":"202211"},"relativePath":"202211/20221019.2 ⭐️  How to Clean Up Snap Versions to Free Up Disk Space.md","filePath":"[post].md"}'),u={name:"202211/20221019.2 ⭐️  How to Clean Up Snap Versions to Free Up Disk Space.md"};function m(g,p,b,S,w,f){const s=i("Link");return r(),d("div",null,[p[26]||(p[26]=l('<h1 id="如何清理-snap-版本以释放磁盘空间" tabindex="-1">如何清理 Snap 版本以释放磁盘空间 <a class="header-anchor" href="#如何清理-snap-版本以释放磁盘空间" aria-label="Permalink to 如何清理 Snap 版本以释放磁盘空间">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202211/06/082905iomvvhsgoooc5czg.jpg" alt=""></p><blockquote><p>这个带有脚本的快速指南有助于清理旧的 Snap 版本并释放 Ubuntu 系统中的一些磁盘空间。</p></blockquote><p>我正在使用的 Ubuntu 测试系统中的磁盘空间不足。因此，我通过 GNOME 的磁盘使用分析器进行调查，以找出哪个包正在消耗宝贵的 SSD 空间。除了通常的缓存和主目录，令我惊讶的是，我发现 Snap 和 Flatpak 消耗了大量的存储空间。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/03/Snap-size-before-cleanup.jpg" alt="Snap 大小 - 清理前"></p><p>尽管如此，我始终坚持一个规则：除非必要，否则不要使用 Snap 或 Flatpak。这主要是因为它们的安装尺寸和其他问题。我更喜欢原生 deb 和 rpm 包。多年来，我在这个测试系统中安装和移除了一定数量的 Snap 包。</p><p>但卸载后还有问题。Snap 在系统中保留了一些残留文件，一般用户不知道。</p><p>所以我打开了 Snap 文件夹 <code>/var/lib/snapd/snaps</code>，发现 Snap 保留了以前安装/卸载的软件包的旧版本。</p><p>例如，在下图中，你可以看到 GNOME 3.28、3.34 和 Wine 都被删除了。但它们还在那里。发生这种情况是因为 Snap 的设计，它在正确卸载后保留已卸载软件包的版本。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/03/Files-under-snaps-directory.jpg" alt="snaps 目录下的文件"></p><p>或者，你可以在终端中使用：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>snap list --all</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/03/snap-list-all.jpg" alt="snap 列出全部"></p><p>对于保留的版本，默认值为 3。这意味着 Snap 会保留每个软件包的三个旧版本，包括活动版本。如果你对磁盘空间没有限制，这是可以的。</p><p>但是对于服务器和其他情况，这很容易遇到成本问题，它会消耗你的磁盘空间。</p><p>但是，你可以使用以下命令轻松修改计数。该值可以在 2 到 20 之间。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo snap set system refresh.retain=2</span></span></code></pre></div><h3 id="清理-snap-版本" tabindex="-1">清理 Snap 版本 <a class="header-anchor" href="#清理-snap-版本" aria-label="Permalink to 清理 Snap 版本">​</a></h3>',18)),e("p",null,[p[1]||(p[1]=n("在 SuperUser 的一篇文章中，Canonical 的前工程经理 Popey ")),a(s,{href:"https://superuser.com/a/1330590"},{default:t(()=>p[0]||(p[0]=[n("提供了一个简单的脚本")])),_:1}),p[2]||(p[2]=n("，它可以清理旧版本的 Snaps 并保留最新版本。"))]),p[27]||(p[27]=l(`<p>这是我们将用来清理 Snap 的脚本。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>#Removes old revisions of snaps</span></span>
<span class="line"><span>#CLOSE ALL SNAPS BEFORE RUNNING THIS</span></span>
<span class="line"><span>set -eu</span></span>
<span class="line"><span>LANG=en_US.UTF-8 snap list --all | awk &#39;/disabled/{print $1, $3}&#39; |</span></span>
<span class="line"><span>while read snapname revision; do</span></span>
<span class="line"><span>    snap remove &quot;$snapname&quot; --revision=&quot;$revision&quot;</span></span>
<span class="line"><span>done</span></span></code></pre></div><p>将上面的脚本以 <code>.sh</code> 扩展名保存在一个目录中（例如 <code>clean_snap.sh</code>），赋予它可执行权限并运行。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>chmod +x clean_snap.sh</span></span></code></pre></div><p>当我运行脚本后，它减少了很多磁盘空间。该脚本还将显示要删除的包的名称。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/03/Executing-the-script.jpg" alt="执行脚本"></p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/03/Snaps-size-after-cleanup.jpg" alt="清理后的 Snap 大小"></p><h3 id="结束语" tabindex="-1">结束语 <a class="header-anchor" href="#结束语" aria-label="Permalink to 结束语">​</a></h3><p>对于 Snap 的设计效率如何，人们总是争论不休。许多人说，它的设计是坏的，是臃肿的，是消耗系统资源的。这种说法的某些部分是真实的，我不会否认它。如果实施和加强得当，整个沙盒应用的概念是很好的。但我相信，与 Snap 相比，Flatpak 工作做得更好。</p><p>也就是说，我希望这可以帮助你清理一些磁盘空间。尽管它只在 Ubuntu 中进行了测试，但它应该适用于所有支持 Snap 的 Linux 发行版。</p>`,10)),e("p",null,[p[4]||(p[4]=n("此外，请查看我们关于 ")),a(s,{href:"https://www.debugpoint.com/2018/07/4-simple-steps-clean-ubuntu-system-linux/"},{default:t(()=>p[3]||(p[3]=[n("如何清理 Ubuntu")])),_:1}),p[5]||(p[5]=n(" 的指南以及其他步骤。"))]),e("p",null,[p[7]||(p[7]=n("最后，如果你要清理 ")),p[8]||(p[8]=e("strong",null,"Flatpak",-1)),p[9]||(p[9]=n(" 应用，请参阅 ")),a(s,{href:"https://www.debugpoint.com/clean-up-flatpak/"},{default:t(()=>p[6]||(p[6]=[n("这篇指南")])),_:1}),p[10]||(p[10]=n("。"))]),p[28]||(p[28]=e("hr",null,null,-1)),e("p",null,[p[12]||(p[12]=n("via: ")),a(s,{href:"https://www.debugpoint.com/clean-up-snap/"},{default:t(()=>p[11]||(p[11]=[n("https://www.debugpoint.com/clean-up-snap/")])),_:1})]),e("p",null,[p[17]||(p[17]=n("作者：")),a(s,{href:"https://www.debugpoint.com/author/admin1/"},{default:t(()=>p[13]||(p[13]=[n("Arindam")])),_:1}),p[18]||(p[18]=n(" 选题：")),a(s,{href:"https://github.com/lkxed"},{default:t(()=>p[14]||(p[14]=[n("lkxed")])),_:1}),p[19]||(p[19]=n(" 译者：")),a(s,{href:"https://github.com/geekpi"},{default:t(()=>p[15]||(p[15]=[n("geekpi")])),_:1}),p[20]||(p[20]=n(" 校对：")),a(s,{href:"https://github.com/wxy"},{default:t(()=>p[16]||(p[16]=[n("wxy")])),_:1})]),e("p",null,[p[23]||(p[23]=n("本文由 ")),a(s,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>p[21]||(p[21]=[n("LCTT")])),_:1}),p[24]||(p[24]=n(" 原创编译，")),a(s,{href:"https://linux.cn/"},{default:t(()=>p[22]||(p[22]=[n("Linux中国")])),_:1}),p[25]||(p[25]=n(" 荣誉推出"))])])}const C=o(u,[["render",m]]);export{v as __pageData,C as default};
